#!/usr/bin/env node
/**
 * Weekly newsletter sender.
 *
 * Reads the digest generated by fetch-ai-news.mjs (blog/data/ai-news.json),
 * pulls subscribers from the Netlify Forms API (the "newsletter" form on the
 * blog page), and emails the digest over SMTP.
 *
 * Required env (all optional locally — the script skips cleanly when unset):
 *   NETLIFY_AUTH_TOKEN  Netlify personal access token (read forms)
 *   NETLIFY_SITE_ID     Site ID from Netlify site settings
 *   SMTP_HOST/SMTP_PORT/SMTP_USER/SMTP_PASS   any SMTP provider
 *   NEWSLETTER_FROM     From header, e.g. "Pranav Dhawan <you@gmail.com>"
 *                       (defaults to SMTP_USER)
 *   FORCE_SEND=1        bypass the "already sent this week" guard
 *
 */

import { readFile, writeFile } from 'node:fs/promises';
import { fileURLToPath } from 'node:url';
import path from 'node:path';

import { selectForPage, formatDate, escapeHtml, httpsUrl, truncate } from './fetch-ai-news.mjs';
import { unsubscribeToken } from '../netlify/functions/lib/unsubscribe-token.mjs';
import { SUPPRESSION_STORE } from '../netlify/functions/lib/unsubscribe-store.mjs';
import { CONFIRMED_STORE } from '../netlify/functions/lib/confirm-store.mjs';

const ROOT = path.dirname(path.dirname(fileURLToPath(import.meta.url)));
const DATA_FILE = path.join(ROOT, 'blog', 'data', 'ai-news.json');
const STATE_FILE = path.join(ROOT, 'blog', 'data', 'newsletter-state.json');

const SITE_URL = 'https://pranavdhawan.com';
const MIN_DAYS_BETWEEN_SENDS = 6;

// CAN-SPAM requires a valid physical postal address in marketing email, and
// Gmail/Yahoo bulk-sender rules expect one. Set NEWSLETTER_ADDRESS (a GitHub
// Actions secret — see README) to a PO box or virtual mailbox; the fallback is
// deliberately city-level only, because anything more specific would put a home
// address in a public repository and in every message sent.
const MAILING_ADDRESS = cleanEnv(process.env.NEWSLETTER_ADDRESS) ||
  'Pranav Dhawan · Washington, DC, USA';

export const EMAIL_PATTERN = /^[^\s@]+@[^\s@]+\.[^\s@]+$/;

/** One-click unsubscribe URL for a recipient (empty when no secret is set). */
export function unsubscribeUrlFor(email, secret = cleanEnv(process.env.UNSUBSCRIBE_SECRET)) {
  if (!secret) return '';
  const token = unsubscribeToken(email, secret);
  return `${SITE_URL}/.netlify/functions/unsubscribe?e=${encodeURIComponent(email)}&t=${encodeURIComponent(token)}`;
}

/** Env values can pick up BOMs/whitespace when set via shell pipes — sanitize. */
export function cleanEnv(value) {
  return String(value || '').replace(/^﻿/, '').trim();
}

/** Dedupe and validate emails from Netlify form submissions. */
export function extractSubscribers(submissions) {
  const seen = new Set();
  const out = [];
  for (const submission of submissions || []) {
    const email = String(submission?.data?.email || '').trim().toLowerCase();
    if (!EMAIL_PATTERN.test(email) || seen.has(email)) continue;
    seen.add(email);
    out.push(email);
  }
  return out;
}

/** Weekly guard so a repeated manual send does not double-send. */
export function shouldSend(state, now = new Date()) {
  if (process.env.FORCE_SEND === '1') return true;
  if (!state?.lastSent) return true;
  const elapsed = now.getTime() - new Date(state.lastSent).getTime();
  return elapsed >= MIN_DAYS_BETWEEN_SENDS * 86400000;
}

export function buildSubject(updatedIso) {
  return `AI This Week — ${formatDate(updatedIso)}`;
}

function safeItems(items) {
  return items
    .map((item) => ({ ...item, url: httpsUrl(item.url) }))
    .filter((item) => item.url);
}

export function buildEmailHtml(items, updatedIso, { unsubscribeUrl = '', address = MAILING_ADDRESS } = {}) {
  const unsubscribeHtml = unsubscribeUrl
    ? `<a href="${escapeHtml(unsubscribeUrl)}" style="color:#555;">Unsubscribe in one click</a>.`
    : `To unsubscribe, reply to this email with the word &quot;unsubscribe&quot;.`;
  const rows = safeItems(items).map((item) => `
    <tr><td style="padding:0 0 22px 0;">
      <div style="font-size:12px;font-weight:bold;letter-spacing:1px;text-transform:uppercase;color:#b8860b;">
        ${escapeHtml(item.category)} &middot; ${escapeHtml(item.sourceName)}</div>
      <div style="font-size:17px;font-weight:bold;line-height:1.35;margin:4px 0;">
        <a href="${escapeHtml(item.url)}" style="color:#1a1a1a;">${escapeHtml(item.title)}</a></div>
      <div style="font-size:14px;color:#555;line-height:1.55;">
        ${escapeHtml(truncate(item.summary || 'Read the full story at the source.'))}</div>
      <div style="font-size:12px;color:#888;margin-top:4px;">${escapeHtml(formatDate(item.date))}</div>
    </td></tr>`).join('');

  return `<!DOCTYPE html>
<html><body style="margin:0;padding:0;background:#f5f2ea;">
<table role="presentation" width="100%" cellpadding="0" cellspacing="0"><tr><td align="center" style="padding:24px 12px;">
<table role="presentation" width="600" cellpadding="0" cellspacing="0"
  style="max-width:600px;width:100%;background:#ffffff;border:3px solid #1a1a1a;font-family:Arial,Helvetica,sans-serif;">
<tr><td style="background:#FFD600;border-bottom:3px solid #1a1a1a;padding:18px 24px;">
  <div style="font-size:20px;font-weight:bold;letter-spacing:1px;color:#1a1a1a;">AI THIS WEEK</div>
  <div style="font-size:13px;color:#1a1a1a;">${escapeHtml(formatDate(updatedIso))} &middot; curated from official lab blogs, arXiv, and GitHub</div>
</td></tr>
<tr><td style="padding:24px;">
<table role="presentation" width="100%" cellpadding="0" cellspacing="0">${rows}</table>
</td></tr>
<tr><td style="border-top:3px solid #1a1a1a;padding:16px 24px;font-size:12px;color:#888;line-height:1.6;">
  You're receiving this because you subscribed at
  <a href="${SITE_URL}/blog/" style="color:#555;">${SITE_URL.replace('https://', '')}/blog</a>.
  Every story links to its original source &mdash; nothing here is AI-generated.
  ${unsubscribeHtml}
  <br>${escapeHtml(address)}
</td></tr>
</table>
</td></tr></table>
</body></html>`;
}

export function buildEmailText(items, updatedIso, { unsubscribeUrl = '', address = MAILING_ADDRESS } = {}) {
  const lines = safeItems(items).map((item) => [
    `[${item.category} - ${item.sourceName}] ${item.title}`,
    truncate(item.summary || 'Read the full story at the source.'),
    `${formatDate(item.date)} — ${item.url}`,
  ].join('\n'));
  const unsubscribeText = unsubscribeUrl
    ? `Unsubscribe in one click: ${unsubscribeUrl}`
    : 'To unsubscribe, reply to this email with the word "unsubscribe".';
  return [
    `AI THIS WEEK — ${formatDate(updatedIso)}`,
    'Curated from official lab blogs, arXiv, and GitHub.',
    '',
    lines.join('\n\n'),
    '',
    `You subscribed at ${SITE_URL}/blog/. ${unsubscribeText}`,
    address,
  ].join('\n');
}

const SUBMISSIONS_PER_PAGE = 100;
const MAX_SUBMISSION_PAGES = 100; // 10k addresses; a stop so a bad API can't loop forever
const NETLIFY_API_TIMEOUT_MS = 20_000;

/** Raw "newsletter" form submissions from the Netlify API ([] until the form exists). */
export async function fetchSubmissions(token, siteId) {
  const headers = { Authorization: `Bearer ${token}` };
  const formsRes = await fetch(`https://api.netlify.com/api/v1/sites/${siteId}/forms`, {
    headers,
    signal: AbortSignal.timeout(NETLIFY_API_TIMEOUT_MS),
  });
  if (!formsRes.ok) throw new Error(`Netlify forms API: HTTP ${formsRes.status}`);
  const forms = await formsRes.json();
  const form = forms.find((f) => f.name === 'newsletter');
  if (!form) {
    console.log('No "newsletter" form found on the site yet (it appears after the first deploy with the form).');
    return [];
  }
  // Paginate: a single fixed-size request silently truncated the list once the
  // form outgrew one page, dropping the oldest subscribers from every send.
  const all = [];
  for (let page = 1; page <= MAX_SUBMISSION_PAGES; page += 1) {
    const subsRes = await fetch(
      `https://api.netlify.com/api/v1/forms/${form.id}/submissions?per_page=${SUBMISSIONS_PER_PAGE}&page=${page}`,
      { headers, signal: AbortSignal.timeout(NETLIFY_API_TIMEOUT_MS) }
    );
    if (!subsRes.ok) throw new Error(`Netlify submissions API: HTTP ${subsRes.status}`);
    const batch = await subsRes.json();
    if (!Array.isArray(batch) || batch.length === 0) break;
    all.push(...batch);
    if (batch.length < SUBMISSIONS_PER_PAGE) break;
  }
  return all;
}

async function loadJson(file, fallback) {
  try {
    return JSON.parse(await readFile(file, 'utf8'));
  } catch {
    return fallback;
  }
}

/**
 * Emails that hit the one-click unsubscribe endpoint (stored in Netlify Blobs).
 *
 * The unsubscribe function reads this store from inside the Netlify runtime,
 * where getStore() self-configures. The manual sender runs outside that runtime,
 * so the site ID and token have to be passed explicitly or the store throws.
 *
 * Fails CLOSED like readConfirmed(): an empty set here would mail people who
 * explicitly opted out, which is exactly what this list exists to prevent.
 * A skipped week is recoverable; a spam complaint is not.
 */
export function suppressionStoreOptions({
  siteID = cleanEnv(process.env.NETLIFY_SITE_ID),
  token = cleanEnv(process.env.NETLIFY_AUTH_TOKEN),
} = {}) {
  return { name: SUPPRESSION_STORE, siteID, token };
}

export async function readSuppressions(options = {}) {
  try {
    const { getStore } = await import('@netlify/blobs');
    const store = getStore(suppressionStoreOptions(options));
    const { blobs } = await store.list();
    return new Set(blobs.map((b) => b.key.toLowerCase()));
  } catch (error) {
    console.error(`Could not read the suppression list (${error?.message}).`);
    return null;
  }
}

/** Store options for the double opt-in confirmations, same credential handling. */
export function confirmedStoreOptions({
  siteID = cleanEnv(process.env.NETLIFY_SITE_ID),
  token = cleanEnv(process.env.NETLIFY_AUTH_TOKEN),
} = {}) {
  return { name: CONFIRMED_STORE, siteID, token };
}

/**
 * Addresses that clicked the confirmation link (double opt-in).
 *
 * Unlike the suppression list this fails CLOSED: if the store is unreachable we
 * return null and the caller skips the send entirely. Falling back to "mail
 * everyone" on a transient outage would mail unconfirmed addresses, which is
 * the exact thing double opt-in exists to prevent. A skipped week is
 * recoverable; a spam complaint is not.
 */
export async function readConfirmed(options = {}) {
  try {
    const { getStore } = await import('@netlify/blobs');
    const store = getStore(confirmedStoreOptions(options));
    const { blobs } = await store.list();
    return new Set(blobs.map((b) => b.key.toLowerCase()));
  } catch (error) {
    console.warn(`Could not read the confirmed-subscriber list (${error?.message}).`);
    return null;
  }
}

async function main() {
  const [NETLIFY_AUTH_TOKEN, NETLIFY_SITE_ID, SMTP_HOST, SMTP_PORT, SMTP_USER, SMTP_PASS] =
    ['NETLIFY_AUTH_TOKEN', 'NETLIFY_SITE_ID', 'SMTP_HOST', 'SMTP_PORT', 'SMTP_USER', 'SMTP_PASS']
      .map((name) => cleanEnv(process.env[name]));
  const missing = Object.entries({ NETLIFY_AUTH_TOKEN, NETLIFY_SITE_ID, SMTP_HOST, SMTP_USER, SMTP_PASS })
    .filter(([, v]) => !v).map(([k]) => k);
  if (missing.length > 0) {
    console.log(`Newsletter not configured (missing ${missing.join(', ')}) — skipping send.`);
    return;
  }

  const state = await loadJson(STATE_FILE, {});
  const now = new Date();
  if (!shouldSend(state, now)) {
    console.log(`Already sent on ${state.lastSent} — skipping (set FORCE_SEND=1 to override).`);
    return;
  }

  const archive = await loadJson(DATA_FILE, null);
  if (!archive?.items?.length) throw new Error('No digest data — run scripts/fetch-ai-news.mjs first.');
  const items = selectForPage(archive.items, now);
  if (items.length === 0) {
    console.log('No fresh items to send this week — skipping.');
    return;
  }

  const allSubscribers = extractSubscribers(await fetchSubmissions(NETLIFY_AUTH_TOKEN, NETLIFY_SITE_ID));
  const confirmed = await readConfirmed();
  if (confirmed === null) {
    console.error('Confirmed-subscriber store unreachable — skipping this send rather than risk mailing unconfirmed addresses.');
    process.exitCode = 1;
    return;
  }
  const suppressed = await readSuppressions();
  if (suppressed === null) {
    console.error('Suppression store unreachable — skipping this send rather than risk mailing unsubscribed addresses.');
    process.exitCode = 1;
    return;
  }
  const subscribers = allSubscribers.filter((email) => confirmed.has(email) && !suppressed.has(email));
  const unconfirmed = allSubscribers.filter((email) => !confirmed.has(email)).length;
  const skipped = allSubscribers.length - subscribers.length - unconfirmed;
  if (unconfirmed > 0) console.log(`Skipping ${unconfirmed} address(es) that never confirmed (double opt-in).`);
  if (skipped > 0) console.log(`Skipping ${skipped} unsubscribed address(es).`);
  if (subscribers.length === 0) {
    console.log('No confirmed subscribers to send to — nothing to do.');
    return;
  }

  const secret = cleanEnv(process.env.UNSUBSCRIBE_SECRET);
  if (!secret) {
    console.warn('UNSUBSCRIBE_SECRET is not set — sending with a mailto unsubscribe only (no one-click).');
  }

  const { default: nodemailer } = await import('nodemailer');
  const transport = nodemailer.createTransport({
    host: SMTP_HOST,
    port: Number(SMTP_PORT || 587),
    secure: Number(SMTP_PORT) === 465,
    auth: { user: SMTP_USER, pass: SMTP_PASS },
  });

  const from = cleanEnv(process.env.NEWSLETTER_FROM) || SMTP_USER;
  const updatedIso = archive.updated || now.toISOString().slice(0, 10);

  // One-click unsubscribe (RFC 8058) needs a per-recipient link, so send one
  // message each rather than a shared BCC batch.
  let sent = 0;
  const failed = [];
  const persistState = async () => {
    // Written after every recipient, not just at the end: a hard crash
    // mid-loop must not cause the next run to re-mail everyone already sent.
    await writeFile(STATE_FILE, `${JSON.stringify({
      lastSent: now.toISOString(),
      recipients: sent,
      failed: failed.length,
      items: items.length,
    }, null, 2)}\n`);
  };

  for (const email of subscribers) {
    const unsubscribeUrl = secret ? unsubscribeUrlFor(email, secret) : '';
    // When the one-click URL exists it is the only List-Unsubscribe URI — some
    // receivers otherwise pick the mailto and degrade one-click to a compose.
    const listUnsubscribe = unsubscribeUrl
      ? `<${unsubscribeUrl}>`
      : `<mailto:${SMTP_USER}?subject=unsubscribe>`;
    const headers = { 'List-Unsubscribe': listUnsubscribe };
    if (unsubscribeUrl) headers['List-Unsubscribe-Post'] = 'List-Unsubscribe=One-Click';

    // Isolate per recipient: an unhandled throw here used to abort the whole run
    // before the state file was written, so the next run re-sent the digest to
    // everyone who had already received it.
    try {
      await transport.sendMail({
        from,
        to: email,
        subject: buildSubject(updatedIso),
        html: buildEmailHtml(items, updatedIso, { unsubscribeUrl }),
        text: buildEmailText(items, updatedIso, { unsubscribeUrl }),
        headers,
      });
      sent += 1;
    } catch (error) {
      failed.push(email);
      console.warn(`Send failed for ${email}: ${error?.message}`);
    }
    await persistState();
  }

  console.log(`Newsletter sent to ${sent} subscribers (${items.length} items).`);
  if (failed.length > 0) {
    console.warn(`${failed.length} address(es) failed and were not retried.`);
    process.exitCode = 1;
  }
}

if (process.argv[1] && fileURLToPath(import.meta.url) === path.resolve(process.argv[1])) {
  main().catch((err) => {
    console.error(err);
    process.exitCode = 1;
  });
}
